use soroban_sdk::{Env, Address, Vec}; pub enum DataKey { EscrowPayoutAddress(u64), } fn get_fleet_payout(env: Env, fleet_addr: Address, fid: u64) -> Option<Address> { None } pub fn create_escrow(env: Env, delivery_id: u64, fleet_addr: Option<Address>, fid: Option<u64>) { let payout_address = if let (Some(fleet_addr), Some(fid)) = (fleet_addr, fid) { get_fleet_payout(env.clone(), fleet_addr, fid) } else { None }; if let Some(payout_address) = payout_address { let payout_key = DataKey::EscrowPayoutAddress(delivery_id); env.storage().persistent().set(&payout_key, &payout_address); } } pub fn create_escrows_batch(env: Env, delivery_ids: Vec<u64>, fleet_addrs: Vec<Option<Address>>, fids: Vec<Option<u64>>) { for i in 0..delivery_ids.len() { let delivery_id = delivery_ids.get(i).unwrap(); let fleet_addr = fleet_addrs.get(i).unwrap(); let fid = fids.get(i).unwrap(); let payout_address = if let (Some(fleet_addr), Some(fid)) = (fleet_addr, fid) { get_fleet_payout(env.clone(), fleet_addr, fid) } else { None }; if let Some(payout_address) = payout_address { let payout_key = DataKey::EscrowPayoutAddress(delivery_id); env.storage().persistent().set(&payout_key, &payout_address); } } }